"""Parsing a double-entry journal into transactions."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal, InvalidOperation

# Account and amount are separated by two or more spaces, so an account name
# may itself contain single spaces.
POSTING_SPLIT = re.compile(r"\s{2,}")
AMOUNT = re.compile(r"^(?P<qty>[-+]?[\d,]*\.?\d+)\s+(?P<cur>\S+)$")


@dataclass(frozen=True)
class Amount:
    quantity: Decimal
    currency: str

    def __str__(self) -> str:
        return f"{self.quantity:,.2f} {self.currency}"


@dataclass
class Posting:
    account: str
    amount: Amount | None
    line: int
    path: str


@dataclass
class Transaction:
    date: date
    payee: str
    postings: list[Posting]
    line: int
    path: str


@dataclass
class Error:
    path: str
    line: int
    message: str

    def __str__(self) -> str:
        return f"{self.path}:{self.line}: {self.message}"


@dataclass
class Journal:
    transactions: list[Transaction] = field(default_factory=list)
    errors: list[Error] = field(default_factory=list)


def parse_amount(text: str) -> Amount | None:
    m = AMOUNT.match(text)
    if not m:
        return None
    try:
        qty = Decimal(m.group("qty").replace(",", ""))
    except InvalidOperation:
        return None
    return Amount(qty, m.group("cur"))


def parse_string(text: str, path: str = "<string>") -> Journal:
    journal = Journal()
    current: Transaction | None = None

    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.rstrip()
        if not line.strip():
            current = None
            continue

        if line[0].isspace():
            if current is None:
                journal.errors.append(
                    Error(path, lineno, "posting outside of any transaction")
                )
                continue
            posting = _parse_posting(line.strip(), lineno, path, journal)
            if posting is not None:
                current.postings.append(posting)
            continue

        current = _parse_header(line, lineno, path, journal)
        if current is not None:
            journal.transactions.append(current)

    return journal


def _parse_header(line: str, lineno: int, path: str, journal: Journal) -> Transaction | None:
    datestr, _, payee = line.partition(" ")
    try:
        when = date.fromisoformat(datestr)
    except ValueError:
        journal.errors.append(
            Error(path, lineno, f"expected a date or a directive, got {line!r}")
        )
        return None
    return Transaction(when, payee.strip(), [], lineno, path)


def _parse_posting(line: str, lineno: int, path: str, journal: Journal) -> Posting | None:
    account, _, rest = (p.strip() for p in _split_posting(line))
    if not account:
        journal.errors.append(Error(path, lineno, "posting has no account"))
        return None
    if not rest:
        return Posting(account, None, lineno, path)
    amount = parse_amount(rest)
    if amount is None:
        journal.errors.append(Error(path, lineno, f"malformed amount {rest!r}"))
        return None
    return Posting(account, amount, lineno, path)


def _split_posting(line: str) -> tuple[str, str, str]:
    parts = POSTING_SPLIT.split(line, maxsplit=1)
    return (parts[0], "", parts[1] if len(parts) > 1 else "")
